const products=[
 {id:1,name:'Muse Dome Ring',price:3499,tag:'rings',image:'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=750&q=85'},
 {id:2,name:'Sol Link Chain',price:4999,tag:'chains',image:'https://images.unsplash.com/photo-1599643477877-530eb83abc8e?auto=format&fit=crop&w=750&q=85'},
 {id:3,name:'Arc Mini Hoops',price:2799,tag:'earrings',image:'https://images.unsplash.com/photo-1635767798638-3e25273a8236?auto=format&fit=crop&w=750&q=85'},
 {id:4,name:'Tide Cuff Bracelet',price:4299,tag:'chains',image:'https://images.unsplash.com/photo-1617038220319-276d3cfab638?auto=format&fit=crop&w=750&q=85'},
 {id:5,name:'Nova Signet Ring',price:3899,tag:'rings',image:'https://images.unsplash.com/photo-1619119069152-a2b331eb392a?auto=format&fit=crop&w=750&q=85'},
 {id:6,name:'Fleur Drop Earrings',price:3199,tag:'earrings',image:'https://images.unsplash.com/photo-1573408301185-9146fe634ad0?auto=format&fit=crop&w=750&q=85'},
 {id:7,name:'Atlas Curb Chain',price:5599,tag:'chains',image:'https://images.unsplash.com/photo-1611085583191-a3b181a88401?auto=format&fit=crop&w=750&q=85'},
 {id:8,name:'Eclipse Band',price:2999,tag:'rings',image:'https://images.unsplash.com/photo-1603561596112-db1d1c8e52d3?auto=format&fit=crop&w=750&q=85'}
];
let cart=[]; const money=n=>'₹'+n.toLocaleString('en-IN');
// Replace this value before launch with the Rare Jewellery business WhatsApp number, including country code.
const WHATSAPP_NUMBER='918421022419';
const grid=document.querySelector('#productGrid'),cartEl=document.querySelector('#cart'),overlay=document.querySelector('#overlay');
function renderProducts(filter='all'){grid.innerHTML=products.filter(p=>filter==='all'||p.tag===filter).map(p=>`<article class="product"><div class="product-image"><img src="${p.image}" alt="${p.name}" loading="lazy"/><span class="product-tag">${p.tag}</span></div><div class="product-info"><div><h3>${p.name}</h3><p>${money(p.price)}</p></div><button class="add" aria-label="Add ${p.name} to bag" data-id="${p.id}">+</button></div></article>`).join('');}
function renderCart(){document.querySelector('#bagCount').textContent=cart.length;const holder=document.querySelector('#cartItems');holder.innerHTML=cart.length?cart.map((p,i)=>`<div class="cart-row"><img src="${p.image}" alt=""><div><h3>${p.name}</h3><p>${money(p.price)}</p><button data-remove="${i}">Remove</button></div></div>`).join(''):'<p class="empty">Your bag is waiting for something beautiful.</p>';document.querySelector('#subtotal').textContent=money(cart.reduce((sum,p)=>sum+p.price,0));}
function openCart(){cartEl.classList.add('open');overlay.classList.add('show');cartEl.setAttribute('aria-hidden','false')} function closeCart(){cartEl.classList.remove('open');overlay.classList.remove('show');cartEl.setAttribute('aria-hidden','true')}
function whatsappOrder(){const items=cart.length?cart.map(p=>`• ${p.name} — ${money(p.price)}`).join('\n'):'I would like help choosing jewellery.';window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent('Hello Rare Jewellery!\n'+items)}`,'_blank','noopener');}
document.addEventListener('click',e=>{const add=e.target.closest('.add');if(add){cart.push(products.find(p=>p.id===Number(add.dataset.id)));renderCart();openCart()}if(e.target.matches('[data-remove]')){cart.splice(Number(e.target.dataset.remove),1);renderCart()}});document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.filter.active').classList.remove('active');b.classList.add('active');renderProducts(b.dataset.filter)}));document.querySelector('#bagButton').addEventListener('click',openCart);document.querySelector('#closeCart').addEventListener('click',closeCart);overlay.addEventListener('click',closeCart);document.querySelector('#checkout').addEventListener('click',whatsappOrder);['#whatsappFloat','#footerWhatsApp','#heroWhatsApp'].forEach(s=>document.querySelector(s).addEventListener('click',e=>{e.preventDefault();whatsappOrder()}));document.querySelector('#newsletterForm').addEventListener('submit',async e=>{e.preventDefault();const email=document.querySelector('#email').value;try{await fetch('/api/lead',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,source:'newsletter'})});document.querySelector('#formMessage').textContent='You’re on the list — welcome to Rare.';e.target.reset()}catch{document.querySelector('#formMessage').textContent='Thanks — we’ll be in touch soon.'}});renderProducts();renderCart();
